import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// The game's sound effects, one per meaningful moment. Files live in
/// assets/sounds and are generated by tool/make_sounds.py.
enum Sfx {
  rotate('rotate'),
  lock('lock'),
  hardDrop('hard_drop'),
  clear('clear'),
  clearFour('clear_four'),
  levelUp('level_up'),
  gameOver('game_over');

  const Sfx(this.file);

  final String file;
}

/// Plays [Sfx] through preloaded audio pools, so repeated sounds (a run of
/// rotations) can overlap instead of cutting each other off.
///
/// The audio session is "ambient": sounds obey the silent switch, mix with
/// whatever music the player already has on, and never take audio focus.
/// Sound is decoration, so any platform failure is logged and ignored.
class SoundEffects {
  final Map<Sfx, AudioPool> _pools = {};

  static final _context = AudioContext(
    iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient, options: const {}),
    android: const AudioContextAndroid(
      contentType: AndroidContentType.sonification,
      usageType: AndroidUsageType.game,
      audioFocus: AndroidAudioFocus.none,
    ),
  );

  /// Prepares every sound. Sounds requested before this finishes are skipped,
  /// and a sound that fails to load stays silent without affecting the rest.
  Future<void> load() async {
    try {
      await AudioPlayer.global.setAudioContext(_context);
    } catch (e) {
      debugPrint('Audio session not configured: $e');
    }
    for (final sfx in Sfx.values) {
      try {
        _pools[sfx] = await AudioPool.create(
          source: AssetSource('sounds/${sfx.file}.wav'),
          audioContext: _context,
          maxPlayers: sfx == Sfx.rotate || sfx == Sfx.lock ? 4 : 2,
        );
      } catch (e) {
        debugPrint('Sound ${sfx.file} unavailable: $e');
      }
    }
  }

  void play(Sfx sfx) {
    final pool = _pools[sfx];
    if (pool == null) return;
    unawaited(pool.start().then((_) {}, onError: (Object e) => debugPrint('Could not play ${sfx.file}: $e')));
  }

  Future<void> dispose() async {
    final pools = _pools.values.toList();
    _pools.clear();
    for (final pool in pools) {
      await pool.dispose();
    }
  }
}
